<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';require __DIR__.'/discord-support.php';
if(PHP_SAPI!=='cli'||getenv('APP_ENV')!=='test'||getenv('DB_DATABASE')!=='levelingwiki_test')exit(1);
function hierarchyCheck(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);echo "OK : $label\n";}
$p=App\Services\Database::connect();seedDiscordRoles($p);$m='200000000000000001';$e='200000000000000002';$a='200000000000000003';
foreach([[[$m],'member'],[[$e],'editor'],[[$a],'admin'],[[$m,$e],'editor'],[[$m,$a],'admin'],[[$e,$a],'admin'],[[$m,$e,$a],'admin']] as $n=>[$roles,$expected]){$id='10000000000000100'.$n;$c=discordLogin($id,$roles);$q=$p->prepare('SELECT u.role FROM users u JOIN discord_identities d ON d.user_id=u.id WHERE d.discord_user_id=?');$q->execute([$id]);hierarchyCheck($q->fetchColumn()===$expected,'OU combinaison '.$n.' → '.$expected);}
foreach([[],['200000000000009999']] as $roles)hierarchyCheck(discordFlow(new HttpTestClient(),'100000000000001100',$roles)['status']===403,'aucun rôle configuré refusé');
$clients=['member'=>discordLogin('100000000000001101',[$m]),'editor'=>discordLogin('100000000000001102',[$e]),'admin'=>discordLogin('100000000000001103',[$a])];$creds=json_decode(file_get_contents('/tmp/levelingwiki-test-admin.json'),true);$clients['super_admin']=new HttpTestClient();$clients['super_admin']->login($creds['username'],$creds['password']);
$ranks=['member'=>1,'editor'=>2,'admin'=>3,'super_admin'=>4];$url='/admin/settings/discord';
foreach($clients as $role=>$c){foreach(['member','editor','admin'] as $level){$allowed=$ranks[$role]>$ranks[$level];$rid='200000000000001'.($ranks[$role]).'0'.$ranks[$level];$data=['action'=>'save','level'=>$level,'discord_role_id'=>$rid,'label'=>'Hiérarchie'];$r=$c->post($url,$data);hierarchyCheck($r['status']===($allowed?303:403),$role.' ajout '.$level);if($allowed){$q=$p->prepare('SELECT id FROM discord_roles WHERE level=? AND discord_role_id=?');$q->execute([$level,$rid]);$id=$q->fetchColumn();$r=$c->post($url,[...$data,'association_id'=>$id,'label'=>'Renommé']);hierarchyCheck($r['status']===303,$role.' renomme '.$level);$r=$c->post($url,[...$data,'association_id'=>$id,'action'=>'delete']);hierarchyCheck($r['status']===303,$role.' retire '.$level);}}}
$editor=$clients['editor'];$admin=$clients['admin'];$adminRow=$p->query("SELECT * FROM discord_roles WHERE level='admin' LIMIT 1")->fetch();
foreach([$editor,$admin] as $c){$r=$c->post($url,['action'=>'save','association_id'=>$adminRow['id'],'level'=>'member','discord_role_id'=>$adminRow['discord_role_id'],'label'=>'Forcé']);hierarchyCheck($r['status']===403,'identifiant association privilégiée forgé refusé');}
$memberRow=$p->query("SELECT * FROM discord_roles WHERE level='member' LIMIT 1")->fetch();
foreach(['editor','admin'] as $target){$r=$editor->post($url,['action'=>'save','association_id'=>$memberRow['id'],'level'=>$target,'discord_role_id'=>$memberRow['discord_role_id'],'label'=>'Élévation']);hierarchyCheck($r['status']===403,'cible supérieure refusée : '.$target);}
$r=$editor->post($url,['action'=>'save','association_id'=>$memberRow['id'],'level'=>'member','discord_role_id'=>'200000000000009998','label'=>'Identifiant changé']);hierarchyCheck($r['status']===403,'Discord Role ID existant immuable');
$version=(int)$p->query('SELECT version FROM authorization_policy WHERE id=1')->fetchColumn();$data=['action'=>'save','level'=>'member','association_id'=>$memberRow['id'],'discord_role_id'=>$memberRow['discord_role_id'],'label'=>$memberRow['label'],'policy_version'=>$version];
hierarchyCheck($editor->post($url,$data)['status']===303,'première version acceptée');hierarchyCheck($editor->post($url,$data)['status']===409,'version périmée refusée');hierarchyCheck($editor->post($url,[...$data,'csrf'=>'forged'])['status']===403,'CSRF forgé refusé');
// Sensitive accesses always refresh, regardless of cache age.
mockDiscord(['user'=>['id'=>'100000000000001103','roles'=>[$m]]]);expireDiscordCache($admin);hierarchyCheck($admin->request($url)['status']===403&&$admin->request('/profil')['status']===200,'ADMIN devient MEMBER sans perte de consultation');
mockDiscord(['user'=>['id'=>'100000000000001102','roles'=>[$a]]]);expireDiscordCache($editor);hierarchyCheck($editor->request($url)['status']===200&&str_contains($editor->request($url)['body'],'+ Ajouter un rôle EDITOR'),'EDITOR seul devient ADMIN après actualisation');
mockDiscord(['user'=>['id'=>'100000000000001102','roles'=>[]]]);expireDiscordCache($editor);hierarchyCheck($editor->request($url)['status']===403&&$editor->request('/profil')['status']===403,'dernier rôle retiré révoque tout accès');
hierarchyCheck((int)$p->query("SELECT COUNT(*) FROM users WHERE role='super_admin' AND auth_provider='discord'")->fetchColumn()===0,'aucun SUPER_ADMIN Discord');
